package com.immortal.launcher.jarvis.wake

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The Kotlin frontend against the TFLite Micro C library. `wake/microfrontend-synthetic.txt` holds the C frontend's
 * features for [signal] (strict IEEE build, regenerated by tools/wake/microfrontend_vectors.py): silence, quiet
 * noise, tones, a clipped loud tone, a faint tone and full-scale noise, so every shift, clamp and the noise floor
 * are exercised. No recorded audio is involved. (Also checked by hand: 14.8k frames of speech and music, 0 diffs.)
 */
class MicroFrontendTest {
  @Test fun matchesTheCLibraryBitForBit() {
    val expected = javaClass.classLoader!!.getResource("wake/microfrontend-synthetic.txt")!!.readText()
        .lines().filter { it.isNotBlank() }.map { line -> line.split(' ').map(String::toInt).toIntArray() }
    val actual = run(signal(SAMPLES))
    assertEquals(expected.size, actual.size)
    expected.indices.forEach { assertArrayEquals("frame $it", expected[it], actual[it]) }
  }

  @Test fun theFirstFrameNeedsAFullThirtyMilliseconds() {
    val frontend = MicroFrontend()
    val pcm = ByteArray(2 * MicroFrontend.STEP)
    val features = IntArray(40)
    assertFalse(frontend.process(pcm, 0, features))
    assertFalse(frontend.process(pcm, 0, features))
    assertTrue(frontend.process(pcm, 0, features))
    assertTrue(frontend.process(pcm, 0, features))
  }

  @Test fun resetStartsAgainFromSilence() {
    val pcm = pcmOf(signal(SAMPLES))
    val fresh = run(signal(SAMPLES))
    val frontend = MicroFrontend()
    val features = IntArray(40)
    for (offset in 0 until pcm.size / 2 step 2 * MicroFrontend.STEP) frontend.process(pcm, offset, features)
    frontend.reset()
    val again = ArrayList<IntArray>()
    for (offset in 0..pcm.size - 2 * MicroFrontend.STEP step 2 * MicroFrontend.STEP) {
      if (frontend.process(pcm, offset, features)) again.add(features.copyOf())
    }
    assertEquals(fresh.size, again.size)
    fresh.indices.forEach { assertArrayEquals(fresh[it], again[it]) }
  }

  private fun run(samples: IntArray): List<IntArray> {
    val pcm = pcmOf(samples)
    val frontend = MicroFrontend()
    val features = IntArray(40)
    val frames = ArrayList<IntArray>()
    for (offset in 0..pcm.size - 2 * MicroFrontend.STEP step 2 * MicroFrontend.STEP) {
      if (frontend.process(pcm, offset, features)) frames.add(features.copyOf())
    }
    return frames
  }

  private fun pcmOf(samples: IntArray): ByteArray = ByteArray(samples.size * 2).also { out ->
    samples.forEachIndexed { i, s ->
      out[2 * i] = (s and 0xFF).toByte()
      out[2 * i + 1] = (s shr 8).toByte()
    }
  }

  private companion object {
    const val SAMPLES = 48_000

    /** The integer-only generator mirrored in the vector script (an LCG plus a stepped triangle wave). */
    fun signal(count: Int): IntArray {
      var state = 12345L
      return IntArray(count) { n ->
        state = (state * 1664525L + 1013904223L) and 0xFFFF_FFFFL
        val noise = (state ushr 16).toInt() - 32768
        val period = 18 + (n / 800) % 70
        val phase = n % period
        val tri = if (phase < period / 2) Math.floorDiv(4 * 8000 * phase, period) - 16000
        else 16000 - Math.floorDiv(4 * 8000 * (phase - period / 2), period)
        val s = when ((n / 4000) % 6) {
          0 -> 0
          1 -> noise shr 6
          2 -> tri + (noise shr 4)
          3 -> 3 * tri + (noise shr 2)
          4 -> (tri shr 3) + (noise shr 9)
          else -> noise
        }
        s.coerceIn(-32768, 32767)
      }
    }
  }
}
